contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint ticket) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (ticket)); require(ticket <= 1000000000000000000000000000000);
        require(ticket == 10);
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        c.play{value: ticket}(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        assert(
            (potAfter == potBefore + ticket && address(c).balance == cBalBefore + ticket)
            ||
            (potAfter == 0 && address(c).balance <= cBalBefore + ticket)
        );
    }
    receive() external payable {}
}

