// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 ticket) internal {
        ticket = bound(ticket, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        ticket = 10;
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        try c.play{value: ticket}() {} catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue((potAfter == potBefore + ticket && address(c).balance == cBalBefore + ticket)
            ||
            (potAfter == 0 && address(c).balance <= cBalBefore + ticket));
    }

    function testFuzz_run(uint256 ticket) public {
        _run(ticket);
    }

    receive() external payable {}
}
